let PublicAIData = externaldata(
    Provider:string,
    Product:string,
    Domain:string,
    Category:string,
    Sanctioned:bool,
    RiskType:string,
    SourceURL:string,
    ProcessName:string,
    ProcessProductName:string,
    ProcessPublisher:string
)
[
    @"https://raw.githubusercontent.com/Azure/Azure-Sentinel/master/Sample%20Data/AIGovernance/ai_domains.csv"
]
with (
    format="csv",
    ignoreFirstRecord=true
)
| extend Sanctioned=false, CatalogueSource="Public", SourcePriority=1
| extend PolicyKey=trim(@"^-+|-+$", replace_regex(tolower(strcat(Provider,"-",Product)), @"[^a-z0-9]+", "-"))
| extend MatchKey=case(
    isnotempty(Domain), strcat("domain:",tolower(trim(@"^\s+|\s+$",Domain))),
    isnotempty(ProcessName), strcat("process:",tolower(trim(@"^\s+|\s+$",ProcessName))),
    strcat("product:",tolower(trim(@"^\s+|\s+$",Provider)),"|",tolower(trim(@"^\s+|\s+$",Product)))
);
let LocalAIData =
    _GetWatchlist('AIGovernance')
    | extend
        W = todynamic(column_ifexists("WatchlistItem", "")),
        DirectKey = tostring(column_ifexists("Key", "")),
        DirectPolicyKey = tostring(column_ifexists("PolicyKey", "")),
        DirectProvider = tostring(column_ifexists("Provider", "")),
        DirectProduct = tostring(column_ifexists("Product", "")),
        DirectDomain = tostring(column_ifexists("Domain", "")),
        DirectCategory = tostring(column_ifexists("Category", "")),
        DirectSanctioned = tostring(column_ifexists("Sanctioned", "")),
        DirectRiskType = tostring(column_ifexists("RiskType", "")),
        DirectSourceURL = tostring(column_ifexists("SourceURL", "")),
        DirectProcessName = tostring(column_ifexists("ProcessName", "")),
        DirectProcessProductName = tostring(column_ifexists("ProcessProductName", "")),
        DirectProcessPublisher = tostring(column_ifexists("ProcessPublisher", "")),
        DirectSearchKey = tostring(column_ifexists("SearchKey", ""))
    | project
        Key = iff(isnotempty(DirectKey), DirectKey, iff(isnotempty(tostring(W.Key)), tostring(W.Key), DirectSearchKey)),
        PolicyKey = iff(isnotempty(DirectPolicyKey), DirectPolicyKey, tostring(W.PolicyKey)),
        Provider = iff(isnotempty(DirectProvider), DirectProvider, tostring(W.Provider)),
        Product = iff(isnotempty(DirectProduct), DirectProduct, tostring(W.Product)),
        Domain = iff(isnotempty(DirectDomain), DirectDomain, tostring(W.Domain)),
        Category = iff(isnotempty(DirectCategory), DirectCategory, tostring(W.Category)),
        Sanctioned = iff(isnotempty(DirectSanctioned), tobool(DirectSanctioned), tobool(W.Sanctioned)),
        RiskType = iff(isnotempty(DirectRiskType), DirectRiskType, tostring(W.RiskType)),
        SourceURL = iff(isnotempty(DirectSourceURL), DirectSourceURL, tostring(W.SourceURL)),
        ProcessName = iff(isnotempty(DirectProcessName), DirectProcessName, tostring(W.ProcessName)),
        ProcessProductName = iff(isnotempty(DirectProcessProductName), DirectProcessProductName, tostring(W.ProcessProductName)),
        ProcessPublisher = iff(isnotempty(DirectProcessPublisher), DirectProcessPublisher, tostring(W.ProcessPublisher))
    | extend PolicyKey=iff(isnotempty(PolicyKey),PolicyKey,Key), CatalogueSource="Local Watchlist", SourcePriority=2
    | extend MatchKey=case(
        isnotempty(Domain), strcat("domain:",tolower(trim(@"^\s+|\s+$",Domain))),
        isnotempty(ProcessName), strcat("process:",tolower(trim(@"^\s+|\s+$",ProcessName))),
        strcat("product:",tolower(trim(@"^\s+|\s+$",Provider)),"|",tolower(trim(@"^\s+|\s+$",Product)))
    );
let AIData =
    union PublicAIData, LocalAIData
    | where isnotempty(PolicyKey)
    | summarize arg_max(SourcePriority, *) by MatchKey
    | project Provider,Product,Domain,Category,Sanctioned,RiskType,SourceURL,ProcessName,ProcessProductName,ProcessPublisher,PolicyKey,CatalogueSource;
let AIDomains =
    toscalar(
        AIData
        | where isnotempty(Domain)
        | summarize
            make_set(
                Domain,
                1000
            )
    );
// ============================================================
// CUSTOMER-SELECTED SANCTIONED POLICY KEYS
//
// The parameter now contains values such as:
//
//   microsoft-copilot
//   openai-chatgpt
//   openai-codex
//   github-copilot
//
// rather than domain names.
// ============================================================
let SanctionedPolicies =
    dynamic([{Sanctioned}]);
// ============================================================
// NETWORK ACTIVITY
// ============================================================
let NetworkActivity =
    DeviceNetworkEvents
    | where Timestamp between (
        {TimeRange:start}
        ..
        {TimeRange:end}
    )
    | where isnotempty(InitiatingProcessAccountUpn)
        or isnotempty(InitiatingProcessAccountName)
    | where isnotempty(RemoteUrl)
    | project
        User = iff(
            isnotempty(InitiatingProcessAccountUpn),
            InitiatingProcessAccountUpn,
            InitiatingProcessAccountName
        ),
        RemoteUrl = tostring(RemoteUrl)
    | extend RemoteUrlLower = tolower(RemoteUrl)
    // Keep the cheap catalogue pre-filter, but do not cross-join events
    // to every catalogue domain.
    | where has_any_index(RemoteUrlLower, AIDomains) >= 0
    | extend
        UrlNoQuery =
            replace_regex(
                RemoteUrlLower,
                @"[?#].*$",
                ""
            )
    | extend
        UrlNoScheme =
            replace_regex(
                UrlNoQuery,
                @"^https?://",
                ""
            )
    | extend
        UrlMatchKeys = pack_array(
            strcat(
                "host:",
                tostring(split(UrlNoScheme, "/")[0])
            ),
            strcat(
                "path:",
                UrlNoScheme
            )
        )
    | mv-expand MatchKey = UrlMatchKeys
    | extend MatchKey = tostring(MatchKey)
    | where isnotempty(MatchKey)
    | summarize by User, MatchKey
    | join kind=inner hint.strategy=broadcast (
        AIData
        | where isnotempty(Domain)
        | extend DomainKey =
            replace_regex(
                tolower(
                    trim(
                        @"^\s+|\s+$",
                        Domain
                    )
                ),
                @"^https?://",
                ""
            )
        | extend DomainKey =
            replace_regex(
                DomainKey,
                @"/+$",
                ""
            )
        | extend DomainMatchKey =
            iff(
                DomainKey contains "/",
                strcat("path:", DomainKey),
                strcat("host:", DomainKey)
            )
        | project
            DomainMatchKey,
            Provider,
            Product,
            Domain,
            PolicyKey
        | distinct
            DomainMatchKey,
            Provider,
            Product,
            Domain,
            PolicyKey
    ) on $left.MatchKey == $right.DomainMatchKey
    | extend IsSanctioned =
        array_length(
            SanctionedPolicies
        ) > 0
        and set_has_element(
            SanctionedPolicies,
            PolicyKey
        )
    | project
        User,
        Provider,
        Product,
        Domain,
        PolicyKey,
        IsSanctioned;
// ============================================================
// DESKTOP CLIENT CATALOGUE
// ============================================================
let AIProcesses =
    AIData
    | where isnotempty(ProcessName)
        or isnotempty(ProcessProductName)
        or isnotempty(ProcessPublisher)
        or PolicyKey in (
            "openai-chatgpt",
            "anthropic-claude",
            "anthropic-claude-code"
        )
    | project
        Provider,
        Product,
        Domain,
        PolicyKey,
        CatalogueProcessName =
            ProcessName,
        CatalogueProductName =
            ProcessProductName,
        CataloguePublisher =
            ProcessPublisher;
// ============================================================
// DESKTOP CLIENT ACTIVITY
// ============================================================
let DesktopActivity =
    DeviceProcessEvents
    | where Timestamp between (
        {TimeRange:start}
        ..
        {TimeRange:end}
    )
    | where isnotempty(AccountUpn)
    or isnotempty(AccountName)
    | extend
        ProcessNameLower =
            tolower(FileName),
        ProductNameLower =
            tolower(
                ProcessVersionInfoProductName
            ),
        PublisherLower =
            tolower(
                ProcessVersionInfoCompanyName
            )
    | extend
        PathMatchKey = case(
            FolderPath contains "ChatGPT.app", "path:openai-chatgpt",
            FolderPath contains "Claude.app", "path:anthropic-claude",
            FolderPath contains "ClaudeCode.app", "path:anthropic-claude-code",
            FolderPath contains "@anthropic-ai/claude-code", "path:anthropic-claude-code",
            ""
        )
    | extend
        MatchKeys = pack_array(
            iff(isnotempty(ProcessNameLower), strcat("process:", ProcessNameLower), ""),
            PathMatchKey
        )
    | mv-expand MatchKey = MatchKeys
    | extend MatchKey = tostring(MatchKey)
    | where isnotempty(MatchKey)
    | project
        User = iff(isnotempty(AccountUpn), AccountUpn, AccountName),
        ProductNameLower,
        PublisherLower,
        HasProductName = isnotempty(ProductNameLower),
        HasPublisher = isnotempty(PublisherLower),
        MatchKey
    | summarize by
        User,
        ProductNameLower,
        PublisherLower,
        HasProductName,
        HasPublisher,
        MatchKey
    | join kind=inner hint.strategy=broadcast (
        AIProcesses
        | extend
            ProcessNameLower =
                tolower(
                    CatalogueProcessName
                ),
            CatalogueProductNameLower =
                tolower(
                    CatalogueProductName
                ),
            CataloguePublisherLower =
                tolower(
                    CataloguePublisher
                )
        | extend
            CataloguePathKey = case(
                PolicyKey == "openai-chatgpt", "path:openai-chatgpt",
                PolicyKey == "anthropic-claude", "path:anthropic-claude",
                PolicyKey == "anthropic-claude-code", "path:anthropic-claude-code",
                ""
            )
        | extend
            MatchKeys = pack_array(
                iff(isnotempty(ProcessNameLower), strcat("process:", ProcessNameLower), ""),
                CataloguePathKey
            )
        | mv-expand MatchKey = MatchKeys
        | extend MatchKey = tostring(MatchKey)
        | where isnotempty(MatchKey)
    ) on MatchKey
    // --------------------------------------------------------
    // VALIDATE PRODUCT
    // --------------------------------------------------------
    | where
        isempty(
            CatalogueProductName
        )
        or ProductNameLower
            == CatalogueProductNameLower
        or not(HasProductName)
    // --------------------------------------------------------
    // VALIDATE PUBLISHER
    // --------------------------------------------------------
    | where
        isempty(
            CataloguePublisher
        )
        or PublisherLower has
            CataloguePublisherLower
        or not(HasPublisher)
    // --------------------------------------------------------
    // GOVERNANCE
    //
    // This is where the policy-key design matters:
    //
    // Process-only products such as Codex can now be
    // sanctioned even when they have no Domain.
    // --------------------------------------------------------
    | extend IsSanctioned =
        array_length(
            SanctionedPolicies
        ) > 0
        and set_has_element(
            SanctionedPolicies,
            PolicyKey
        )
    | project
        User,
        Provider,
        Product,
        Domain,
        PolicyKey,
        IsSanctioned;
// ============================================================
// COMBINE AND DEDUPLICATE
//
// One row per:
//
//   User
//   Provider
//   Product
//   PolicyKey
//
// Domain is deliberately not the governance identity anymore.
// ============================================================
let AIUsage =
    union
        NetworkActivity,
        DesktopActivity
    | where isnotempty(User)
    | summarize
        IsSanctioned =
            max(IsSanctioned),
        Domains =
            make_set_if(
                Domain,
                isnotempty(Domain),
                20
            )
      by
        User,
        Provider,
        Product,
        PolicyKey;
// ============================================================
// USER GOVERNANCE
//
// A user may be:
//
//   🟢 Sanctioned only
//   🟠 Mixed
//   🔴 Unsanctioned only
// ============================================================
let UserGovernance =
    AIUsage
    | summarize
        SanctionedProducts =
            dcountif(
                PolicyKey,
                IsSanctioned
            ),
        UnsanctionedProducts =
            dcountif(
                PolicyKey,
                not(IsSanctioned)
            )
      by User
    | extend Governance =
        case(
            SanctionedProducts > 0
                and UnsanctionedProducts > 0,
                "Mixed",
            UnsanctionedProducts > 0,
                "Unsanctioned only",
            SanctionedProducts > 0,
                "Sanctioned only",
            "Review"
        );
// ============================================================
// HEADLINE VALUES
// ============================================================
let TotalUsers =
    toscalar(
        UserGovernance
        | summarize count()
    );
let TotalProviders =
    toscalar(
        AIUsage
        | where isnotempty(Provider)
        | summarize
            dcount(Provider)
    );
let TotalProducts =
    toscalar(
        AIUsage
        | where isnotempty(PolicyKey)
        | summarize
            dcount(PolicyKey)
    );
let UnsanctionedUsers =
    toscalar(
        UserGovernance
        | where Governance ==
            "Unsanctioned only"
        | summarize count()
    );
let MixedUsers =
    toscalar(
        UserGovernance
        | where Governance ==
            "Mixed"
        | summarize count()
    );
let SanctionedUsers =
    toscalar(
        UserGovernance
        | where Governance ==
            "Sanctioned only"
        | summarize count()
    );
// ============================================================
// TILE OUTPUT
// ============================================================
union
    (
        print
            SortOrder = 1,
            Metric =
                "👥 AI Users Observed",
            Value =
                tolong(TotalUsers)
    ),
    (
        print
            SortOrder = 2,
            Metric =
                "🏢 AI Providers Observed",
            Value =
                tolong(TotalProviders)
    ),
    (
        print
            SortOrder = 3,
            Metric =
                "🤖 AI Products Observed",
            Value =
                tolong(TotalProducts)
    ),
    (
        print
            SortOrder = 4,
            Metric =
                "🔴 Unsanctioned-only Users",
            Value =
                tolong(
                    UnsanctionedUsers
                )
    ),
    (
        print
            SortOrder = 5,
            Metric =
                "🟠 Mixed Users",
            Value =
                tolong(
                    MixedUsers
                )
    ),
    (
        print
            SortOrder = 6,
            Metric =
                "🟢 Sanctioned-only Users",
            Value =
                tolong(
                    SanctionedUsers
                )
    )
| order by
    SortOrder asc
| project
    Metric,
    Value

// ============================================================
// SANCTIONED AI ADOPTION
//
// Shows how much of the customer-selected sanctioned AI
// policy has actually been observed during the selected
// Workbook TimeRange.
//
// Output:
//   🏢 Providers   observed / configured
//   🤖 Products    observed / configured
//   ⚪ Not Observed sanctioned products not seen
//
// Uses:
//   - Public AI catalogue
//   - Optional AIGovernance watchlist
//   - Customer-selected {Sanctioned} PolicyKeys
//   - DeviceNetworkEvents
//   - DeviceProcessEvents
// ============================================================


// ============================================================
// PUBLIC AI CATALOGUE
// ============================================================

let PublicAIData =
    externaldata(
        Provider:string,
        Product:string,
        Domain:string,
        Category:string,
        Sanctioned:bool,
        RiskType:string,
        SourceURL:string,
        ProcessName:string,
        ProcessProductName:string,
        ProcessPublisher:string
    )
    [
        @"https://raw.githubusercontent.com/Azure/Azure-Sentinel/master/Sample%20Data/AIGovernance/ai_domains.csv"
    ]
    with (
        format="csv",
        ignoreFirstRecord=true
    )

    | extend
        Sanctioned = false,
        CatalogueSource = "Public",
        SourcePriority = 1

    | extend PolicyKey =
        trim(
            @"^-+|-+$",
            replace_regex(
                tolower(
                    strcat(
                        Provider,
                        "-",
                        Product
                    )
                ),
                @"[^a-z0-9]+",
                "-"
            )
        )

    | extend MatchKey =
        case(
            isnotempty(Domain),
                strcat(
                    "domain:",
                    tolower(
                        trim(
                            @"^\s+|\s+$",
                            Domain
                        )
                    )
                ),

            isnotempty(ProcessName),
                strcat(
                    "process:",
                    tolower(
                        trim(
                            @"^\s+|\s+$",
                            ProcessName
                        )
                    )
                ),

            strcat(
                "product:",
                tolower(
                    trim(
                        @"^\s+|\s+$",
                        Provider
                    )
                ),
                "|",
                tolower(
                    trim(
                        @"^\s+|\s+$",
                        Product
                    )
                )
            )
        );


// ============================================================
// OPTIONAL LOCAL AIGOVERNANCE WATCHLIST
//
// Direct Watchlist access is intentional.
//
// If the watchlist does not exist, this returns no local rows
// and the public catalogue continues to work normally.
//
// The raw Watchlist table may contain historical versions,
// therefore only the latest row per SearchKey is retained.
// ============================================================

let LocalAIData =
    _GetWatchlist('AIGovernance')
    | extend
        W = todynamic(column_ifexists("WatchlistItem", "")),
        DirectKey = tostring(column_ifexists("Key", "")),
        DirectPolicyKey = tostring(column_ifexists("PolicyKey", "")),
        DirectProvider = tostring(column_ifexists("Provider", "")),
        DirectProduct = tostring(column_ifexists("Product", "")),
        DirectDomain = tostring(column_ifexists("Domain", "")),
        DirectCategory = tostring(column_ifexists("Category", "")),
        DirectSanctioned = tostring(column_ifexists("Sanctioned", "")),
        DirectRiskType = tostring(column_ifexists("RiskType", "")),
        DirectSourceURL = tostring(column_ifexists("SourceURL", "")),
        DirectProcessName = tostring(column_ifexists("ProcessName", "")),
        DirectProcessProductName = tostring(column_ifexists("ProcessProductName", "")),
        DirectProcessPublisher = tostring(column_ifexists("ProcessPublisher", "")),
        DirectSearchKey = tostring(column_ifexists("SearchKey", ""))
    | project
        Key = iff(isnotempty(DirectKey), DirectKey, iff(isnotempty(tostring(W.Key)), tostring(W.Key), DirectSearchKey)),
        PolicyKey = iff(isnotempty(DirectPolicyKey), DirectPolicyKey, tostring(W.PolicyKey)),
        Provider = iff(isnotempty(DirectProvider), DirectProvider, tostring(W.Provider)),
        Product = iff(isnotempty(DirectProduct), DirectProduct, tostring(W.Product)),
        Domain = iff(isnotempty(DirectDomain), DirectDomain, tostring(W.Domain)),
        Category = iff(isnotempty(DirectCategory), DirectCategory, tostring(W.Category)),
        Sanctioned = iff(isnotempty(DirectSanctioned), tobool(DirectSanctioned), tobool(W.Sanctioned)),
        RiskType = iff(isnotempty(DirectRiskType), DirectRiskType, tostring(W.RiskType)),
        SourceURL = iff(isnotempty(DirectSourceURL), DirectSourceURL, tostring(W.SourceURL)),
        ProcessName = iff(isnotempty(DirectProcessName), DirectProcessName, tostring(W.ProcessName)),
        ProcessProductName = iff(isnotempty(DirectProcessProductName), DirectProcessProductName, tostring(W.ProcessProductName)),
        ProcessPublisher = iff(isnotempty(DirectProcessPublisher), DirectProcessPublisher, tostring(W.ProcessPublisher))
    | extend PolicyKey=iff(isnotempty(PolicyKey),PolicyKey,Key), CatalogueSource="Local Watchlist", SourcePriority=2
    | extend MatchKey=case(
        isnotempty(Domain), strcat("domain:",tolower(trim(@"^\s+|\s+$",Domain))),
        isnotempty(ProcessName), strcat("process:",tolower(trim(@"^\s+|\s+$",ProcessName))),
        strcat("product:",tolower(trim(@"^\s+|\s+$",Provider)),"|",tolower(trim(@"^\s+|\s+$",Product)))
    );


// ============================================================
// EFFECTIVE AI CATALOGUE
//
// Local evidence overrides matching public evidence.
// Multiple evidence rows may share the same PolicyKey.
// ============================================================

let AIData =
    union
        PublicAIData,
        LocalAIData

    | where isnotempty(PolicyKey)

    | summarize
        arg_max(
            SourcePriority,
            *
        )
      by MatchKey

    | project
        Provider,
        Product,
        Domain,
        Category,
        RiskType,
        SourceURL,
        ProcessName,
        ProcessProductName,
        ProcessPublisher,
        PolicyKey,
        CatalogueSource;


// ============================================================
// CUSTOMER-SELECTED SANCTIONED POLICIES
// ============================================================

let SanctionedPolicies =
    dynamic([{Sanctioned}]);


// ============================================================
// SANCTIONED POLICY INVENTORY
//
// One logical row per configured PolicyKey.
// ============================================================

let SanctionedInventory =
    AIData

    | where
        array_length(
            SanctionedPolicies
        ) > 0

    | where set_has_element(
        SanctionedPolicies,
        PolicyKey
    )

    | summarize
        Provider =
            take_any(Provider),

        Product =
            take_any(Product)

      by PolicyKey;


// ============================================================
// KNOWN AI DOMAINS
// ============================================================

let AIDomains =
    toscalar(
        AIData

        | where isnotempty(Domain)

        | summarize
            make_set(
                Domain,
                1000
            )
    );


// ============================================================
// NETWORK OBSERVATIONS
// ============================================================

let NetworkObserved =
    DeviceNetworkEvents

    | where Timestamp between (
        {TimeRange:start}
        ..
        {TimeRange:end}
    )

    | where isnotempty(InitiatingProcessAccountUpn)
    or isnotempty(InitiatingProcessAccountName)

    | where isnotempty(RemoteUrl)

    | where has_any_index(tolower(RemoteUrl), AIDomains) >= 0

    | project
        RemoteUrl

    | extend RemoteUrlLower = tolower(RemoteUrl)
    | extend UrlNoQuery = replace_regex(RemoteUrlLower, @"[?#].*$", "")
    | extend UrlNoScheme = replace_regex(UrlNoQuery, @"^https?://", "")
    | extend UrlMatchKeys = pack_array(
        strcat("host:", tostring(split(UrlNoScheme, "/")[0])),
        strcat("path:", UrlNoScheme)
    )
    | mv-expand MatchKey = UrlMatchKeys
    | extend MatchKey = tostring(MatchKey)
    | where isnotempty(MatchKey)
    | project
        Timestamp = todatetime(column_ifexists("Timestamp", "")),
        User = tostring(column_ifexists("User", "")),
        DeviceId = tostring(column_ifexists("DeviceId", "")),
        DeviceName = tostring(column_ifexists("DeviceName", "")),
        RemoteUrl = tostring(RemoteUrl),
        Process = tostring(column_ifexists("Process", "")),
        MatchKey
    | distinct Timestamp, User, DeviceId, DeviceName, RemoteUrl, Process, MatchKey
    | join kind=inner hint.strategy=broadcast (
        AIData
        | where isnotempty(Domain)
        | extend DomainKey = replace_regex(tolower(trim(@"^\s+|\s+$", Domain)), @"^https?://", "")
        | extend DomainKey = replace_regex(DomainKey, @"/+$", "")
        | extend DomainMatchKey = iff(DomainKey contains "/", strcat("path:", DomainKey), strcat("host:", DomainKey))
        | project DomainMatchKey, Provider, Product, Domain, PolicyKey, Category, RiskType
        | distinct DomainMatchKey, Provider, Product, Domain, PolicyKey, Category, RiskType
    ) on $left.MatchKey == $right.DomainMatchKey

    | where
        array_length(
            SanctionedPolicies
        ) > 0

    | where set_has_element(
        SanctionedPolicies,
        PolicyKey
    )

    | project
        Provider,
        Product,
        PolicyKey;


// ============================================================
// DESKTOP / PROCESS CATALOGUE
// ============================================================

let AIProcesses =
    AIData

    | where isnotempty(ProcessName)
        or isnotempty(ProcessProductName)
        or isnotempty(ProcessPublisher)
        or PolicyKey in (
            "openai-chatgpt",
            "anthropic-claude",
            "anthropic-claude-code"
        )

    | project
        Provider,
        Product,
        PolicyKey,

        CatalogueProcessName =
            ProcessName,

        CatalogueProductName =
            ProcessProductName,

        CataloguePublisher =
            ProcessPublisher;


// ============================================================
// DESKTOP / PROCESS OBSERVATIONS
// ============================================================

let DesktopObserved =
    DeviceProcessEvents

    | where Timestamp between (
        {TimeRange:start}
        ..
        {TimeRange:end}
    )

    | where isnotempty(AccountUpn)
    or isnotempty(AccountName)

    | extend
        ProcessNameLower =
            tolower(FileName),

        ProductNameLower =
            tolower(
                ProcessVersionInfoProductName
            ),

        PublisherLower =
            tolower(
                ProcessVersionInfoCompanyName
            )

    | extend

        PathMatchKey = case(
            FolderPath contains "ChatGPT.app", "path:openai-chatgpt",
            FolderPath contains "Claude.app", "path:anthropic-claude",
            FolderPath contains "ClaudeCode.app", "path:anthropic-claude-code",
            FolderPath contains "@anthropic-ai/claude-code", "path:anthropic-claude-code",
            ""
        )

    | extend

        MatchKeys = pack_array(
            iff(isnotempty(ProcessNameLower), strcat("process:", ProcessNameLower), ""),
            PathMatchKey
        )

    | mv-expand MatchKey = MatchKeys

    | extend MatchKey = tostring(MatchKey)

    | where isnotempty(MatchKey)

    | project
        Timestamp,
        User = iff(isnotempty(AccountUpn), AccountUpn, AccountName),
        AccountUpn,
        AccountName,
        DeviceId,
        DeviceName,
        ProcessNameLower,
        ProductNameLower,
        PublisherLower,
        HasProductName = isnotempty(ProductNameLower),
        HasPublisher = isnotempty(PublisherLower),
        MatchKey
    | summarize by Timestamp, User, AccountUpn, AccountName, DeviceId, DeviceName, ProcessNameLower, ProductNameLower, PublisherLower, HasProductName, HasPublisher, MatchKey

    | join kind=inner hint.strategy=broadcast (
        AIProcesses

        | extend
            ProcessNameLower =
                tolower(
                    CatalogueProcessName
                ),

            CatalogueProductNameLower =
                tolower(
                    CatalogueProductName
                ),

            CataloguePublisherLower =
                tolower(
                    CataloguePublisher
                )

        | extend

            CataloguePathKey = case(
                PolicyKey == "openai-chatgpt", "path:openai-chatgpt",
                PolicyKey == "anthropic-claude", "path:anthropic-claude",
                PolicyKey == "anthropic-claude-code", "path:anthropic-claude-code",
                ""
            )

        | extend

            MatchKeys = pack_array(
                iff(isnotempty(ProcessNameLower), strcat("process:", ProcessNameLower), ""),
                CataloguePathKey
            )

        | mv-expand MatchKey = MatchKeys

        | extend MatchKey = tostring(MatchKey)

        | where isnotempty(MatchKey)

    ) on MatchKey

    | where
        isempty(
            CatalogueProductName
        )
        or ProductNameLower
            == CatalogueProductNameLower
        or not(HasProductName)

    | where
        isempty(
            CataloguePublisher
        )
        or PublisherLower has
            CataloguePublisherLower
        or not(HasPublisher)

    | where
        array_length(
            SanctionedPolicies
        ) > 0

    | where set_has_element(
        SanctionedPolicies,
        PolicyKey
    )

    | project
        Provider,
        Product,
        PolicyKey;


// ============================================================
// OBSERVED SANCTIONED POLICIES
//
// Collapse network and process evidence back to the logical
// PolicyKey so multiple evidence types do not inflate counts.
// ============================================================

let ObservedSanctioned =
    union
        NetworkObserved,
        DesktopObserved

    | summarize
        Provider =
            take_any(Provider),

        Product =
            take_any(Product)

      by PolicyKey;


// ============================================================
// HEADLINE VALUES
// ============================================================

let SanctionedProductsConfigured =
    toscalar(
        SanctionedInventory
        | summarize
            dcount(PolicyKey)
    );

let SanctionedProvidersConfigured =
    toscalar(
        SanctionedInventory

        | where isnotempty(Provider)

        | summarize
            dcount(Provider)
    );

let SanctionedProductsObserved =
    toscalar(
        ObservedSanctioned

        | summarize
            dcount(PolicyKey)
    );

let SanctionedProvidersObserved =
    toscalar(
        ObservedSanctioned

        | where isnotempty(Provider)

        | summarize
            dcount(Provider)
    );

let SanctionedProductsNotObserved =
    tolong(
        SanctionedProductsConfigured
        -
        SanctionedProductsObserved
    );


// ============================================================
// COMPACT TILE OUTPUT
// ============================================================

union
    (
        print
            SortOrder = 1,
            Metric = "🏢 Providers",
            Value = strcat(
                tostring(SanctionedProvidersObserved),
                " / ",
                tostring(SanctionedProvidersConfigured)
            ),
            Detail = "Observed / Configured"
    ),
    (
        print
            SortOrder = 2,
            Metric = "🤖 Products",
            Value = strcat(
                tostring(SanctionedProductsObserved),
                " / ",
                tostring(SanctionedProductsConfigured)
            ),
            Detail = "Observed / Configured"
    ),
    (
        print
            SortOrder = 3,
            Metric = "⚪ Not Observed",
            Value = tostring(SanctionedProductsNotObserved),
            Detail = iff(
                SanctionedProductsNotObserved == 1,
                "Sanctioned product",
                "Sanctioned products"
            )
    )

| order by SortOrder asc

| project
    Metric,
    Value,
    Detail

// ============================================================
// AI PROVIDERS & PRODUCTS OBSERVED - TILE SUMMARY
//
// One row per provider.
//
// Product governance is based ONLY on the customer-selected
// {Sanctioned} services.
//
// Provider governance:
//   🟢 Sanctioned only
//   🟠 Mixed
//   🔴 Unsanctioned only
//
// Individual products are also prefixed with 🟢 / 🔴.
// ============================================================


// ============================================================
// AI SERVICE CATALOGUE
// ============================================================

let PublicAIData = externaldata(
    Provider:string,
    Product:string,
    Domain:string,
    Category:string,
    Sanctioned:bool,
    RiskType:string,
    SourceURL:string,
    ProcessName:string,
    ProcessProductName:string,
    ProcessPublisher:string
)
[
    @"https://raw.githubusercontent.com/Azure/Azure-Sentinel/master/Sample%20Data/AIGovernance/ai_domains.csv"
]
with (
    format="csv",
    ignoreFirstRecord=true
)
| extend Sanctioned=false, CatalogueSource="Public", SourcePriority=1
| extend PolicyKey=trim(@"^-+|-+$", replace_regex(tolower(strcat(Provider,"-",Product)), @"[^a-z0-9]+", "-"))
| extend MatchKey=case(
    isnotempty(Domain), strcat("domain:",tolower(trim(@"^\s+|\s+$",Domain))),
    isnotempty(ProcessName), strcat("process:",tolower(trim(@"^\s+|\s+$",ProcessName))),
    strcat("product:",tolower(trim(@"^\s+|\s+$",Provider)),"|",tolower(trim(@"^\s+|\s+$",Product)))
);

let LocalAIData =
    _GetWatchlist('AIGovernance')
    | extend
        W = todynamic(column_ifexists("WatchlistItem", "")),
        DirectKey = tostring(column_ifexists("Key", "")),
        DirectPolicyKey = tostring(column_ifexists("PolicyKey", "")),
        DirectProvider = tostring(column_ifexists("Provider", "")),
        DirectProduct = tostring(column_ifexists("Product", "")),
        DirectDomain = tostring(column_ifexists("Domain", "")),
        DirectCategory = tostring(column_ifexists("Category", "")),
        DirectSanctioned = tostring(column_ifexists("Sanctioned", "")),
        DirectRiskType = tostring(column_ifexists("RiskType", "")),
        DirectSourceURL = tostring(column_ifexists("SourceURL", "")),
        DirectProcessName = tostring(column_ifexists("ProcessName", "")),
        DirectProcessProductName = tostring(column_ifexists("ProcessProductName", "")),
        DirectProcessPublisher = tostring(column_ifexists("ProcessPublisher", "")),
        DirectSearchKey = tostring(column_ifexists("SearchKey", ""))
    | project
        Key = iff(isnotempty(DirectKey), DirectKey, iff(isnotempty(tostring(W.Key)), tostring(W.Key), DirectSearchKey)),
        PolicyKey = iff(isnotempty(DirectPolicyKey), DirectPolicyKey, tostring(W.PolicyKey)),
        Provider = iff(isnotempty(DirectProvider), DirectProvider, tostring(W.Provider)),
        Product = iff(isnotempty(DirectProduct), DirectProduct, tostring(W.Product)),
        Domain = iff(isnotempty(DirectDomain), DirectDomain, tostring(W.Domain)),
        Category = iff(isnotempty(DirectCategory), DirectCategory, tostring(W.Category)),
        Sanctioned = iff(isnotempty(DirectSanctioned), tobool(DirectSanctioned), tobool(W.Sanctioned)),
        RiskType = iff(isnotempty(DirectRiskType), DirectRiskType, tostring(W.RiskType)),
        SourceURL = iff(isnotempty(DirectSourceURL), DirectSourceURL, tostring(W.SourceURL)),
        ProcessName = iff(isnotempty(DirectProcessName), DirectProcessName, tostring(W.ProcessName)),
        ProcessProductName = iff(isnotempty(DirectProcessProductName), DirectProcessProductName, tostring(W.ProcessProductName)),
        ProcessPublisher = iff(isnotempty(DirectProcessPublisher), DirectProcessPublisher, tostring(W.ProcessPublisher))
    | extend PolicyKey=iff(isnotempty(PolicyKey),PolicyKey,Key), CatalogueSource="Local Watchlist", SourcePriority=2
    | extend MatchKey=case(
        isnotempty(Domain), strcat("domain:",tolower(trim(@"^\s+|\s+$",Domain))),
        isnotempty(ProcessName), strcat("process:",tolower(trim(@"^\s+|\s+$",ProcessName))),
        strcat("product:",tolower(trim(@"^\s+|\s+$",Provider)),"|",tolower(trim(@"^\s+|\s+$",Product)))
    );

let AIData =
    union PublicAIData, LocalAIData
    | where isnotempty(PolicyKey)
    | summarize arg_max(SourcePriority, *) by MatchKey
    | project Provider,Product,Domain,Category,Sanctioned,RiskType,SourceURL,ProcessName,ProcessProductName,ProcessPublisher,PolicyKey,CatalogueSource;

let AIDomainData = AIData;


// ============================================================
// KNOWN AI DOMAINS
// ============================================================

let AIDomains =
    toscalar(
        AIDomainData
        | where isnotempty(Domain)
        | summarize make_set(Domain)
    );


// ============================================================
// CUSTOMER-SELECTED SANCTIONED SERVICES
//
// IMPORTANT:
// Governance is based on this Workbook parameter only.
//
// If no services are selected, no recognised AI service is
// treated as sanctioned.
// ============================================================

let SanctionedPolicies = dynamic([{Sanctioned}]);


// ============================================================
// KNOWN BROWSERS
// ============================================================

let Browsers = dynamic([
    "msedge.exe",
    "chrome.exe",
    "firefox.exe",
    "brave.exe",
    "opera.exe",
    "iexplore.exe"
]);


// ============================================================
// NETWORK ACTIVITY
// ============================================================

let NetworkActivity =
    DeviceNetworkEvents

    | where Timestamp between ({TimeRange:start} .. {TimeRange:end})

    | where isnotempty(InitiatingProcessAccountUpn)
    or isnotempty(InitiatingProcessAccountName)

    | where isnotempty(RemoteUrl)

    | where has_any_index(tolower(RemoteUrl), AIDomains) >= 0

    | project
        Timestamp,
        User = iff(isnotempty(InitiatingProcessAccountUpn), InitiatingProcessAccountUpn, InitiatingProcessAccountName),
        DeviceId,
        DeviceName,
        RemoteUrl,
        Process = InitiatingProcessFileName

    | extend RemoteUrlLower = tolower(RemoteUrl)
    | extend UrlNoQuery = replace_regex(RemoteUrlLower, @"[?#].*$", "")
    | extend UrlNoScheme = replace_regex(UrlNoQuery, @"^https?://", "")
    | extend UrlMatchKeys = pack_array(
        strcat("host:", tostring(split(UrlNoScheme, "/")[0])),
        strcat("path:", UrlNoScheme)
    )
    | mv-expand MatchKey = UrlMatchKeys
    | extend MatchKey = tostring(MatchKey)
    | where isnotempty(MatchKey)
    | project
        Timestamp = todatetime(column_ifexists("Timestamp", "")),
        User = tostring(column_ifexists("User", "")),
        DeviceId = tostring(column_ifexists("DeviceId", "")),
        DeviceName = tostring(column_ifexists("DeviceName", "")),
        RemoteUrl = tostring(RemoteUrl),
        Process = tostring(column_ifexists("Process", "")),
        MatchKey
    | distinct Timestamp, User, DeviceId, DeviceName, RemoteUrl, Process, MatchKey
    | join kind=inner hint.strategy=broadcast (
        AIData
        | where isnotempty(Domain)
        | extend DomainKey = replace_regex(tolower(trim(@"^\s+|\s+$", Domain)), @"^https?://", "")
        | extend DomainKey = replace_regex(DomainKey, @"/+$", "")
        | extend DomainMatchKey = iff(DomainKey contains "/", strcat("path:", DomainKey), strcat("host:", DomainKey))
        | project DomainMatchKey, Provider, Product, Domain, PolicyKey, Category, RiskType
        | distinct DomainMatchKey, Provider, Product, Domain, PolicyKey, Category, RiskType
    ) on $left.MatchKey == $right.DomainMatchKey

    // --------------------------------------------------------
    // GOVERNANCE
    //
    // Exact membership check.
    //
    // Do NOT use:
    //     set_has_element(SanctionedPolicies, PolicyKey)
    //
    // set_has_element() checks whether this exact domain is
    // present in the customer-selected sanctioned array.
    // --------------------------------------------------------

    | extend IsSanctioned =
        array_length(SanctionedPolicies) > 0
        and set_has_element(
            SanctionedPolicies,
            PolicyKey
        )

    // --------------------------------------------------------
    // ACCESS TYPE
    // --------------------------------------------------------

    | extend IsBrowser =
        Process in~ (Browsers)

    | extend IsAPI =
        RiskType =~ "API"
        or Category =~ "API"
        or Product has "API"

    | extend IsDeveloper =
        RiskType =~ "Developer"
        or Category =~ "Developer"

    | extend AccessType =
        case(
            IsBrowser,
                "Web / Browser",

            IsAPI or IsDeveloper,
                "API / Developer",

            "Non-browser Network"
        )

    | project
        Timestamp,
        Provider,
        Product,
        Domain,
        PolicyKey,
        IsSanctioned,
        User,
        DeviceId,
        DeviceName,
        AccessType;


// ============================================================
// DESKTOP CLIENT CATALOGUE
// ============================================================

let AIProcesses =
    AIDomainData

    | where isnotempty(ProcessName)
        or isnotempty(ProcessProductName)
        or isnotempty(ProcessPublisher)
        or PolicyKey in (
            "openai-chatgpt",
            "anthropic-claude",
            "anthropic-claude-code"
        )

    | project
        Provider,
        Product,
        Domain,
        PolicyKey,
        CatalogueProcessName = ProcessName,
        CatalogueProductName = ProcessProductName,
        CataloguePublisher = ProcessPublisher;


// ============================================================
// DESKTOP CLIENT ACTIVITY
// ============================================================

let DesktopActivity =
    DeviceProcessEvents

    | where Timestamp between ({TimeRange:start} .. {TimeRange:end})

    | where isnotempty(AccountUpn)
    or isnotempty(AccountName)

    | extend
        ProcessNameLower =
            tolower(FileName),

        ProductNameLower =
            tolower(ProcessVersionInfoProductName),

        PublisherLower =
            tolower(ProcessVersionInfoCompanyName)

    | extend

        PathMatchKey = case(
            FolderPath contains "ChatGPT.app", "path:openai-chatgpt",
            FolderPath contains "Claude.app", "path:anthropic-claude",
            FolderPath contains "ClaudeCode.app", "path:anthropic-claude-code",
            FolderPath contains "@anthropic-ai/claude-code", "path:anthropic-claude-code",
            ""
        )

    | extend

        MatchKeys = pack_array(
            iff(isnotempty(ProcessNameLower), strcat("process:", ProcessNameLower), ""),
            PathMatchKey
        )

    | mv-expand MatchKey = MatchKeys

    | extend MatchKey = tostring(MatchKey)

    | where isnotempty(MatchKey)

    | project
        Timestamp,
        User = iff(isnotempty(AccountUpn), AccountUpn, AccountName),
        AccountUpn,
        AccountName,
        DeviceId,
        DeviceName,
        ProcessNameLower,
        ProductNameLower,
        PublisherLower,
        HasProductName = isnotempty(ProductNameLower),
        HasPublisher = isnotempty(PublisherLower),
        MatchKey
    | summarize by Timestamp, User, AccountUpn, AccountName, DeviceId, DeviceName, ProcessNameLower, ProductNameLower, PublisherLower, HasProductName, HasPublisher, MatchKey

    | join kind=inner hint.strategy=broadcast (
        AIProcesses

        | extend
            ProcessNameLower =
                tolower(CatalogueProcessName),

            CatalogueProductNameLower =
                tolower(CatalogueProductName),

            CataloguePublisherLower =
                tolower(CataloguePublisher)

        | extend

            CataloguePathKey = case(
                PolicyKey == "openai-chatgpt", "path:openai-chatgpt",
                PolicyKey == "anthropic-claude", "path:anthropic-claude",
                PolicyKey == "anthropic-claude-code", "path:anthropic-claude-code",
                ""
            )

        | extend

            MatchKeys = pack_array(
                iff(isnotempty(ProcessNameLower), strcat("process:", ProcessNameLower), ""),
                CataloguePathKey
            )

        | mv-expand MatchKey = MatchKeys

        | extend MatchKey = tostring(MatchKey)

        | where isnotempty(MatchKey)

    ) on MatchKey

    // --------------------------------------------------------
    // VALIDATE PRODUCT
    // --------------------------------------------------------

    | where
        isempty(CatalogueProductName)
        or ProductNameLower == CatalogueProductNameLower
        or not(HasProductName)

    // --------------------------------------------------------
    // VALIDATE PUBLISHER
    // --------------------------------------------------------

    | where
        isempty(CataloguePublisher)
        or PublisherLower has CataloguePublisherLower
        or not(HasPublisher)

    // --------------------------------------------------------
    // GOVERNANCE
    //
    // Same exact selection logic as network activity.
    // --------------------------------------------------------

    | extend IsSanctioned =
        array_length(SanctionedPolicies) > 0
        and set_has_element(
            SanctionedPolicies,
            PolicyKey
        )

    | extend AccessType =
        "Desktop Client"

    | project
        Timestamp,
        Provider,
        Product,
        Domain,
        PolicyKey,
        IsSanctioned,
        User = iff(isnotempty(AccountUpn), AccountUpn, AccountName),
        DeviceId,
        DeviceName,
        AccessType;


// ============================================================
// COMBINE ACTIVITY
// ============================================================

let CombinedActivity =
    union
        NetworkActivity,
        DesktopActivity;


// ============================================================
// PRODUCT-LEVEL GOVERNANCE
//
// Create one row per Provider / Product / Domain before rolling
// up to provider level.
//
// The governance indicator comes directly from the exact
// {Sanctioned} policy selection.
// ============================================================

let ProductSummary =
    CombinedActivity

    | summarize
        ProductUsers =
            dcount(User),

        ProductDevices =
            dcount(DeviceId),

        ProductActivity =
            count(),

        FirstSeen =
            min(Timestamp),

        LastSeen =
            max(Timestamp)

      by
        Provider,
        Product,
        Domain,
        PolicyKey,
        IsSanctioned

    | extend ProductGovernance =
        iff(
            IsSanctioned,
            "🟢",
            "🔴"
        )

    | extend ProductLabel =
        strcat(
            ProductGovernance,
            " ",
            Product
        );


// ============================================================
// PROVIDER-LEVEL USER / DEVICE SUMMARY
//
// Calculated directly from CombinedActivity so users are not
// double-counted when they use multiple products from the same
// provider.
// ============================================================

let ProviderUsage =
    CombinedActivity

    | summarize
        Users =
            dcount(User),

        Devices =
            dcount(DeviceId),

        Activity =
            count(),

        AccessTypes =
            make_set_if(
                AccessType,
                isnotempty(AccessType),
                10
            ),

        UserList =
            make_set_if(
                User,
                isnotempty(User),
                50
            ),

        DeviceList =
            make_set_if(
                DeviceName,
                isnotempty(DeviceName),
                50
            ),

        FirstSeen =
            min(Timestamp),

        LastSeen =
            max(Timestamp)

      by Provider;


// ============================================================
// PROVIDER PRODUCT SUMMARY
// ============================================================

let ProviderProducts =
    ProductSummary

    | summarize

        Products =
            dcount(PolicyKey),

        SanctionedProducts =
            dcountif(
                PolicyKey,
                IsSanctioned
            ),

        UnsanctionedProducts =
            dcountif(
                PolicyKey,
                not(IsSanctioned)
            ),

        ProductsUsed =
            make_set(
                ProductLabel,
                50
            ),

        Domains =
            make_set_if(
                Domain,
                isnotempty(Domain),
                50
            )

      by Provider

    // --------------------------------------------------------
    // PROVIDER GOVERNANCE
    // --------------------------------------------------------

    | extend Governance =
        case(
            SanctionedProducts > 0
                and UnsanctionedProducts > 0,
                "🟠 Mixed",

            UnsanctionedProducts > 0,
                "🔴 Unsanctioned only",

            SanctionedProducts > 0,
                "🟢 Sanctioned only",

            "⚪ Review"
        )

    // --------------------------------------------------------
    // FRIENDLY PRODUCT LIST
    // --------------------------------------------------------

    | extend ProductList =
        strcat_array(
            array_sort_asc(ProductsUsed),
            ", "
        )

    | extend ProductDisplay =
        strcat(
            tostring(Products),
            iff(
                Products == 1,
                " product",
                " products"
            )
        );


// ============================================================
// JOIN PROVIDER METRICS
// ============================================================

ProviderProducts

| join kind=inner hint.strategy=broadcast (
    ProviderUsage
) on Provider


// ============================================================
// DISPLAY VALUES
// ============================================================

| extend UserDisplay =
    strcat(
        tostring(Users),
        iff(
            Users == 1,
            " user",
            " users"
        )
    )

| extend AccessTypeList =
    strcat_array(
        array_sort_asc(AccessTypes),
        ", "
    )


// ============================================================
// SORT
// ============================================================

| extend GovernanceSort =
    case(
        Governance == "🔴 Unsanctioned only", 1,
        Governance == "🟠 Mixed", 2,
        Governance == "🟢 Sanctioned only", 3,
        4
    )

| order by
    GovernanceSort asc,
    Users desc,
    Products desc,
    Activity desc


// ============================================================
// OUTPUT
// ============================================================

| project
    Provider,

    Governance,

    Products,

    ['Product List'] =
        ProductList,

    Users,

    UserDisplay,

    ['Sanctioned Products'] =
        SanctionedProducts,

    ['Unsanctioned Products'] =
        UnsanctionedProducts,

    Devices,

    Activity,

    ['Access Type List'] =
        AccessTypeList,

    ['Last Seen'] =
        LastSeen,

    ['First Seen'] =
        FirstSeen

| order by
    Provider asc

// ============================================================
// NEW AI USERS
//
// Observation window: fixed 30 days
// New user: first observed AI activity in last 7 days
//
// Governance:
//   🟢 Sanctioned only
//   🟠 Mixed
//   🔴 Unsanctioned only
//
// If no sanctioned products are selected, all observed
// products are treated as unsanctioned.
// ============================================================


// ============================================================
// AI SERVICE CATALOGUE
// ============================================================

let PublicAIData = externaldata(
    Provider:string,
    Product:string,
    Domain:string,
    Category:string,
    Sanctioned:bool,
    RiskType:string,
    SourceURL:string,
    ProcessName:string,
    ProcessProductName:string,
    ProcessPublisher:string
)
[
    @"https://raw.githubusercontent.com/Azure/Azure-Sentinel/master/Sample%20Data/AIGovernance/ai_domains.csv"
]
with (
    format="csv",
    ignoreFirstRecord=true
)
| extend
    Sanctioned = false,
    CatalogueSource = "Public",
    SourcePriority = 1
| extend PolicyKey =
    trim(
        @"^-+|-+$",
        replace_regex(
            tolower(
                strcat(
                    Provider,
                    "-",
                    Product
                )
            ),
            @"[^a-z0-9]+",
            "-"
        )
    )
| extend MatchKey =
    case(
        isnotempty(Domain),
            strcat(
                "domain:",
                tolower(
                    trim(
                        @"^\s+|\s+$",
                        Domain
                    )
                )
            ),

        isnotempty(ProcessName),
            strcat(
                "process:",
                tolower(
