        isnotempty(ProcessName), strcat("process:",tolower(trim(@"^\s+|\s+$",ProcessName))),
        strcat("product:",tolower(trim(@"^\s+|\s+$",Provider)),"|",tolower(trim(@"^\s+|\s+$",Product)))
    );


// ============================================================
// EFFECTIVE AI CATALOGUE
// ============================================================

let AIData =
    union
        PublicAIData,
        LocalAIData

    | where isnotempty(PolicyKey)

    | summarize
        arg_max(
            SourcePriority,
            *
        )
      by MatchKey

    | project
        Provider,
        Product,
        Domain,
        Category,
        Sanctioned,
        RiskType,
        SourceURL,
        ProcessName,
        ProcessProductName,
        ProcessPublisher,
        PolicyKey,
        CatalogueSource;

let AIDomainData = AIData;


// ============================================================
// KNOWN AI DOMAINS
// ============================================================

let AIDomains =
    toscalar(
        AIDomainData

        | where isnotempty(Domain)

        | summarize
            make_set(
                Domain,
                1000
            )
    );


// ============================================================
// CUSTOMER-SELECTED SANCTIONED SERVICES
// ============================================================

let SanctionedPolicies =
    dynamic([{Sanctioned}]);


// ============================================================
// BROWSERS
// ============================================================

let Browsers =
    dynamic([
        "msedge.exe",
        "chrome.exe",
        "firefox.exe",
        "brave.exe",
        "opera.exe",
        "iexplore.exe"
    ]);


// ============================================================
// OBSERVED AI ACTIVITY
//
// Fixed 30-day window intentionally used here rather than
// Workbook TimeRange so "new" has useful historical context.
// ============================================================

let AIActivity =
    DeviceNetworkEvents

    | where Timestamp >= ago(30d)

    | where has_any_index(tolower(RemoteUrl), AIDomains) >= 0

    | where InitiatingProcessFileName in~ (
        Browsers
    )

    | where isnotempty(InitiatingProcessAccountUpn)
    or isnotempty(InitiatingProcessAccountName)

    | project
        Timestamp,
        User = iff(isnotempty(InitiatingProcessAccountUpn), InitiatingProcessAccountUpn, InitiatingProcessAccountName),
        DeviceId,
        DeviceName,
        RemoteUrl;


// ============================================================
// MAP ACTIVITY TO AI PRODUCTS
// ============================================================

let MappedAIActivity =
    AIActivity

    | extend RemoteUrlLower = tolower(RemoteUrl)
    | extend UrlNoQuery = replace_regex(RemoteUrlLower, @"[?#].*$", "")
    | extend UrlNoScheme = replace_regex(UrlNoQuery, @"^https?://", "")
    | extend UrlMatchKeys = pack_array(
        strcat("host:", tostring(split(UrlNoScheme, "/")[0])),
        strcat("path:", UrlNoScheme)
    )
    | mv-expand MatchKey = UrlMatchKeys
    | extend MatchKey = tostring(MatchKey)
    | where isnotempty(MatchKey)
    | project
        Timestamp = todatetime(column_ifexists("Timestamp", "")),
        User = tostring(column_ifexists("User", "")),
        DeviceId = tostring(column_ifexists("DeviceId", "")),
        DeviceName = tostring(column_ifexists("DeviceName", "")),
        RemoteUrl = tostring(RemoteUrl),
        Process = tostring(column_ifexists("Process", "")),
        MatchKey
    | distinct Timestamp, User, DeviceId, DeviceName, RemoteUrl, Process, MatchKey
    | join kind=inner hint.strategy=broadcast (
        AIData
        | where isnotempty(Domain)
        | extend DomainKey = replace_regex(tolower(trim(@"^\s+|\s+$", Domain)), @"^https?://", "")
        | extend DomainKey = replace_regex(DomainKey, @"/+$", "")
        | extend DomainMatchKey = iff(DomainKey contains "/", strcat("path:", DomainKey), strcat("host:", DomainKey))
        | project DomainMatchKey, Provider, Product, Domain, PolicyKey, Category, RiskType
        | distinct DomainMatchKey, Provider, Product, Domain, PolicyKey, Category, RiskType
    ) on $left.MatchKey == $right.DomainMatchKey

    // Workbook selection is the governance authority.
    | extend IsSanctioned =
        array_length(
            SanctionedPolicies
        ) > 0
        and set_has_element(
            SanctionedPolicies,
            PolicyKey
        )

    // Preserve governance directly in the product label.
    | extend ProductDisplay =
        strcat(
            iff(
                IsSanctioned,
                "🟢 ",
                "🔴 "
            ),
            Product
        )

    | project
        Timestamp,
        User,
        DeviceId,
        DeviceName,
        Provider,
        Product,
        ProductDisplay,
        Domain,
        PolicyKey,
        IsSanctioned;


// ============================================================
// USER SUMMARY
// ============================================================

MappedAIActivity

| summarize

    FirstSeen =
        min(Timestamp),

    LastSeen =
        max(Timestamp),

    Providers =
        dcount(Provider),

    Products =
        dcount(PolicyKey),

    SanctionedProducts =
        dcountif(
            PolicyKey,
            IsSanctioned
        ),

    UnsanctionedProducts =
        dcountif(
            PolicyKey,
            not(IsSanctioned)
        ),

    ProductsObserved =
        make_set(
            ProductDisplay,
            20
        ),

    ProvidersUsed =
        make_set(
            Provider,
            20
        ),

    Devices =
        dcount(DeviceId)

  by User


// ============================================================
// NEW USERS
//
// First observed during the most recent 7 days of the fixed
// 30-day observation window.
// ============================================================

| where FirstSeen >= ago(7d)


// ============================================================
// GOVERNANCE STATUS
// ============================================================

| extend Governance =
    case(
        SanctionedProducts > 0
            and UnsanctionedProducts > 0,
            "🟠 Mixed",

        UnsanctionedProducts > 0,
            "🔴 Unsanctioned only",

        SanctionedProducts > 0,
            "🟢 Sanctioned only",

        "⚪ Review"
    )


// ============================================================
// FRIENDLY LISTS
// ============================================================

| extend ['Products Observed'] =
    strcat_array(
        array_sort_asc(
            ProductsObserved
        ),
        ", "
    )

| extend ['Providers Used'] =
    strcat_array(
        array_sort_asc(
            ProvidersUsed
        ),
        ", "
    )


// ============================================================
// SORT
//
// Unsanctioned first, then mixed, then sanctioned.
// ============================================================

| extend GovernanceSort =
    case(
        Governance == "🔴 Unsanctioned only", 1,
        Governance == "🟠 Mixed", 2,
        Governance == "🟢 Sanctioned only", 3,
        4
    )

| order by
    GovernanceSort asc,
    FirstSeen desc


// ============================================================
// OUTPUT
// ============================================================

| project
    Governance,

    User,

    ['First Seen'] =
        FirstSeen,

    ['Sanctioned Products'] =
        SanctionedProducts,

    ['Unsanctioned Products'] =
        UnsanctionedProducts,

    ['Total Products'] =
        Products,

    ['Products Observed'],

    Providers,

    ['Providers Used'],

    Devices,

    ['Last Seen'] =
        LastSeen

// ============================================================
// AI USAGE & ADOPTION
//
// Shows how regularly recognised AI products are being used
// during the selected Workbook TimeRange.
//
// Measures:
//   - Users
//   - Devices
//   - Active Days
//   - Observed Sessions
//   - Activity Events
//   - First / Last Seen
//
// IMPORTANT:
// "Observed Sessions" are inferred from telemetry.
// A new session starts where more than 30 minutes has elapsed
// since the previous observation for the same user/product.
//
// This is NOT a measure of foreground application time or
// actual time spent using an AI service.
// ============================================================


// ============================================================
// TIME RANGE
// ============================================================

let RangeStart =
    todatetime({TimeRange:start});

let RangeEnd =
    todatetime({TimeRange:end});

let RangeDays =
    datetime_diff(
        "day",
        startofday(RangeEnd),
        startofday(RangeStart)
    ) + 1;


// ============================================================
// PUBLIC AI CATALOGUE
// ============================================================

let PublicAIData =
    externaldata(
        Provider:string,
        Product:string,
        Domain:string,
        Category:string,
        Sanctioned:bool,
        RiskType:string,
        SourceURL:string,
        ProcessName:string,
        ProcessProductName:string,
        ProcessPublisher:string
    )
    [
        @"https://raw.githubusercontent.com/Azure/Azure-Sentinel/master/Sample%20Data/AIGovernance/ai_domains.csv"
    ]
    with (
        format="csv",
        ignoreFirstRecord=true
    )

    | extend
        Sanctioned = false,
        CatalogueSource = "Public",
        SourcePriority = 1

    | extend PolicyKey =
        trim(
            @"^-+|-+$",
            replace_regex(
                tolower(
                    strcat(
                        Provider,
                        "-",
                        Product
                    )
                ),
                @"[^a-z0-9]+",
                "-"
            )
        )

    | extend MatchKey =
        case(
            isnotempty(Domain),
                strcat(
                    "domain:",
                    tolower(
                        trim(@"^\s+|\s+$", Domain)
                    )
                ),

            isnotempty(ProcessName),
                strcat(
                    "process:",
                    tolower(
                        trim(@"^\s+|\s+$", ProcessName)
                    )
                ),

            strcat(
                "product:",
                tolower(
                    trim(@"^\s+|\s+$", Provider)
                ),
                "|",
                tolower(
                    trim(@"^\s+|\s+$", Product)
                )
            )
        );


// ============================================================
// OPTIONAL LOCAL AIGOVERNANCE WATCHLIST
// ============================================================

let LocalAIData =
    _GetWatchlist('AIGovernance')
    | extend
        W = todynamic(column_ifexists("WatchlistItem", "")),
        DirectKey = tostring(column_ifexists("Key", "")),
        DirectPolicyKey = tostring(column_ifexists("PolicyKey", "")),
        DirectProvider = tostring(column_ifexists("Provider", "")),
        DirectProduct = tostring(column_ifexists("Product", "")),
        DirectDomain = tostring(column_ifexists("Domain", "")),
        DirectCategory = tostring(column_ifexists("Category", "")),
        DirectSanctioned = tostring(column_ifexists("Sanctioned", "")),
        DirectRiskType = tostring(column_ifexists("RiskType", "")),
        DirectSourceURL = tostring(column_ifexists("SourceURL", "")),
        DirectProcessName = tostring(column_ifexists("ProcessName", "")),
        DirectProcessProductName = tostring(column_ifexists("ProcessProductName", "")),
        DirectProcessPublisher = tostring(column_ifexists("ProcessPublisher", "")),
        DirectSearchKey = tostring(column_ifexists("SearchKey", ""))
    | project
        Key = iff(isnotempty(DirectKey), DirectKey, iff(isnotempty(tostring(W.Key)), tostring(W.Key), DirectSearchKey)),
        PolicyKey = iff(isnotempty(DirectPolicyKey), DirectPolicyKey, tostring(W.PolicyKey)),
        Provider = iff(isnotempty(DirectProvider), DirectProvider, tostring(W.Provider)),
        Product = iff(isnotempty(DirectProduct), DirectProduct, tostring(W.Product)),
        Domain = iff(isnotempty(DirectDomain), DirectDomain, tostring(W.Domain)),
        Category = iff(isnotempty(DirectCategory), DirectCategory, tostring(W.Category)),
        Sanctioned = iff(isnotempty(DirectSanctioned), tobool(DirectSanctioned), tobool(W.Sanctioned)),
        RiskType = iff(isnotempty(DirectRiskType), DirectRiskType, tostring(W.RiskType)),
        SourceURL = iff(isnotempty(DirectSourceURL), DirectSourceURL, tostring(W.SourceURL)),
        ProcessName = iff(isnotempty(DirectProcessName), DirectProcessName, tostring(W.ProcessName)),
        ProcessProductName = iff(isnotempty(DirectProcessProductName), DirectProcessProductName, tostring(W.ProcessProductName)),
        ProcessPublisher = iff(isnotempty(DirectProcessPublisher), DirectProcessPublisher, tostring(W.ProcessPublisher))
    | extend PolicyKey=iff(isnotempty(PolicyKey),PolicyKey,Key), CatalogueSource="Local Watchlist", SourcePriority=2
    | extend MatchKey=case(
        isnotempty(Domain), strcat("domain:",tolower(trim(@"^\s+|\s+$",Domain))),
        isnotempty(ProcessName), strcat("process:",tolower(trim(@"^\s+|\s+$",ProcessName))),
        strcat("product:",tolower(trim(@"^\s+|\s+$",Provider)),"|",tolower(trim(@"^\s+|\s+$",Product)))
    );


// ============================================================
// EFFECTIVE AI CATALOGUE
// ============================================================

let AIData =
    union
        PublicAIData,
        LocalAIData

    | where isnotempty(PolicyKey)

    | summarize
        arg_max(
            SourcePriority,
            *
        )
      by MatchKey

    | project
        Provider,
        Product,
        Domain,
        Category,
        RiskType,
        ProcessName,
        ProcessProductName,
        ProcessPublisher,
        PolicyKey,
        CatalogueSource;


// ============================================================
// CUSTOMER-SELECTED SANCTIONED POLICIES
//
// JSON formatting is used because Sanctioned is a multi-select
// Workbook parameter containing PolicyKey values.
// ============================================================

// ============================================================
// CUSTOMER-SELECTED SANCTIONED POLICIES
// ============================================================

let SanctionedPolicies =
    dynamic([{Sanctioned}]);


// ============================================================
// KNOWN AI DOMAINS
// ============================================================

let AIDomains =
    toscalar(
        AIData

        | where isnotempty(Domain)

        | summarize
            make_set(
                Domain,
                1000
            )
    );


// ============================================================
// NETWORK ACTIVITY
// ============================================================

let NetworkActivity =
    DeviceNetworkEvents

    | where Timestamp between (
        RangeStart
        ..
        RangeEnd
    )

    | where isnotempty(InitiatingProcessAccountUpn)
    or isnotempty(InitiatingProcessAccountName)

    | where isnotempty(RemoteUrl)

    | where has_any_index(tolower(RemoteUrl), AIDomains) >= 0

    | project
        Timestamp,
        User = iff(isnotempty(InitiatingProcessAccountUpn), InitiatingProcessAccountUpn, InitiatingProcessAccountName),
        DeviceId,
        DeviceName,
        RemoteUrl

    | extend RemoteUrlLower = tolower(RemoteUrl)
    | extend UrlNoQuery = replace_regex(RemoteUrlLower, @"[?#].*$", "")
    | extend UrlNoScheme = replace_regex(UrlNoQuery, @"^https?://", "")
    | extend UrlMatchKeys = pack_array(
        strcat("host:", tostring(split(UrlNoScheme, "/")[0])),
        strcat("path:", UrlNoScheme)
    )
    | mv-expand MatchKey = UrlMatchKeys
    | extend MatchKey = tostring(MatchKey)
    | where isnotempty(MatchKey)
    | project
        Timestamp = todatetime(column_ifexists("Timestamp", "")),
        User = tostring(column_ifexists("User", "")),
        DeviceId = tostring(column_ifexists("DeviceId", "")),
        DeviceName = tostring(column_ifexists("DeviceName", "")),
        RemoteUrl = tostring(RemoteUrl),
        Process = tostring(column_ifexists("Process", "")),
        MatchKey
    | distinct Timestamp, User, DeviceId, DeviceName, RemoteUrl, Process, MatchKey
    | join kind=inner hint.strategy=broadcast (
        AIData
        | where isnotempty(Domain)
        | extend DomainKey = replace_regex(tolower(trim(@"^\s+|\s+$", Domain)), @"^https?://", "")
        | extend DomainKey = replace_regex(DomainKey, @"/+$", "")
        | extend DomainMatchKey = iff(DomainKey contains "/", strcat("path:", DomainKey), strcat("host:", DomainKey))
        | project DomainMatchKey, Provider, Product, Domain, PolicyKey, Category, RiskType
        | distinct DomainMatchKey, Provider, Product, Domain, PolicyKey, Category, RiskType
    ) on $left.MatchKey == $right.DomainMatchKey

    | extend IsSanctioned =
        array_length(
            SanctionedPolicies
        ) > 0
        and set_has_element(
            SanctionedPolicies,
            PolicyKey
        )

    | project
        Timestamp,
        User,
        DeviceId,
        DeviceName,
        Provider,
        Product,
        PolicyKey,
        IsSanctioned,
        EvidenceType = "Network";


// ============================================================
// PROCESS CATALOGUE
// ============================================================

let AIProcesses =
    AIData

    | where isnotempty(ProcessName)
        or isnotempty(ProcessProductName)
        or isnotempty(ProcessPublisher)
        or PolicyKey in (
            "openai-chatgpt",
            "anthropic-claude",
            "anthropic-claude-code"
        )

    | project
        Provider,
        Product,
        PolicyKey,

        CatalogueProcessName =
            ProcessName,

        CatalogueProductName =
            ProcessProductName,

        CataloguePublisher =
            ProcessPublisher;


// ============================================================
// DESKTOP / CLIENT ACTIVITY
// ============================================================

let DesktopActivity =
    DeviceProcessEvents

    | where Timestamp between (
        RangeStart
        ..
        RangeEnd
    )

    | where isnotempty(AccountUpn)
    or isnotempty(AccountName)

    | extend
        ProcessNameLower =
            tolower(FileName),

        ProductNameLower =
            tolower(
                ProcessVersionInfoProductName
            ),

        PublisherLower =
            tolower(
                ProcessVersionInfoCompanyName
            )

    | extend

        PathMatchKey = case(
            FolderPath contains "ChatGPT.app", "path:openai-chatgpt",
            FolderPath contains "Claude.app", "path:anthropic-claude",
            FolderPath contains "ClaudeCode.app", "path:anthropic-claude-code",
            FolderPath contains "@anthropic-ai/claude-code", "path:anthropic-claude-code",
            ""
        )

    | extend

        MatchKeys = pack_array(
            iff(isnotempty(ProcessNameLower), strcat("process:", ProcessNameLower), ""),
            PathMatchKey
        )

    | mv-expand MatchKey = MatchKeys

    | extend MatchKey = tostring(MatchKey)

    | where isnotempty(MatchKey)

    | project
        Timestamp,
        User = iff(isnotempty(AccountUpn), AccountUpn, AccountName),
        AccountUpn,
        AccountName,
        DeviceId,
        DeviceName,
        ProcessNameLower,
        ProductNameLower,
        PublisherLower,
        HasProductName = isnotempty(ProductNameLower),
        HasPublisher = isnotempty(PublisherLower),
        MatchKey
    | summarize by Timestamp, User, AccountUpn, AccountName, DeviceId, DeviceName, ProcessNameLower, ProductNameLower, PublisherLower, HasProductName, HasPublisher, MatchKey

    | join kind=inner hint.strategy=broadcast (
        AIProcesses

        | extend
            ProcessNameLower =
                tolower(
                    CatalogueProcessName
                ),

            CatalogueProductNameLower =
                tolower(
                    CatalogueProductName
                ),

            CataloguePublisherLower =
                tolower(
                    CataloguePublisher
                )

        | extend

            CataloguePathKey = case(
                PolicyKey == "openai-chatgpt", "path:openai-chatgpt",
                PolicyKey == "anthropic-claude", "path:anthropic-claude",
                PolicyKey == "anthropic-claude-code", "path:anthropic-claude-code",
                ""
            )

        | extend

            MatchKeys = pack_array(
                iff(isnotempty(ProcessNameLower), strcat("process:", ProcessNameLower), ""),
                CataloguePathKey
            )

        | mv-expand MatchKey = MatchKeys

        | extend MatchKey = tostring(MatchKey)

        | where isnotempty(MatchKey)

    ) on MatchKey

    | where
        isempty(CatalogueProductName)
        or ProductNameLower
            == CatalogueProductNameLower
        or not(HasProductName)

    | where
        isempty(CataloguePublisher)
        or PublisherLower has
            CataloguePublisherLower
        or not(HasPublisher)

    | extend IsSanctioned =
        array_length(
            SanctionedPolicies
        ) > 0
        and set_has_element(
            SanctionedPolicies,
            PolicyKey
        )

    | project
        Timestamp,
        User = iff(isnotempty(AccountUpn), AccountUpn, AccountName),
        DeviceId,
        DeviceName,
        Provider,
        Product,
        PolicyKey,
        IsSanctioned,
        EvidenceType = "Desktop Client";


// ============================================================
// COMBINED OBSERVATIONS
// ============================================================

let Observations =
    union
        NetworkActivity,
        DesktopActivity

    | where isnotempty(User)
        and isnotempty(PolicyKey)

    // Remove duplicate matches for the same telemetry moment.
    | summarize
        Provider =
            take_any(Provider),

        Product =
            take_any(Product),

        IsSanctioned =
            max(IsSanctioned)

      by
        Timestamp,
        User,
        DeviceId,
        DeviceName,
        PolicyKey;


// ============================================================
// SESSION DETECTION
//
// New session where:
//   - user changes, OR
//   - PolicyKey changes, OR
//   - previous event was more than 30 minutes ago.
//
// This represents an observed telemetry session only.
// ============================================================

let SessionActivity =
    Observations

    | sort by
        User asc,
        PolicyKey asc,
        Timestamp asc

    | serialize

    | extend
        PreviousUser =
            prev(User),

        PreviousPolicyKey =
            prev(PolicyKey),

        PreviousTimestamp =
            prev(Timestamp)

    | extend IsNewSession =
        iff(
            User != PreviousUser
            or PolicyKey != PreviousPolicyKey
            or isnull(PreviousTimestamp)
            or Timestamp >
                PreviousTimestamp + 30m,
            1,
            0
        );


// ============================================================
// EVIDENCE TYPE SUMMARY
//
// Kept separately from the session calculation so evidence
// types do not duplicate session rows.
// ============================================================

let EvidenceSummary =
    union
        NetworkActivity,
        DesktopActivity

    | summarize
        EvidenceTypes =
            make_set(
                EvidenceType,
                10
            )

      by PolicyKey;


// ============================================================
// PRODUCT / POLICY SUMMARY
// ============================================================

let ProductSummary =
    SessionActivity

    | summarize
        Users =
            dcount(User),

        Devices =
            dcount(DeviceId),

        ActiveDays =
            dcount(
                startofday(Timestamp)
            ),

        ObservedSessions =
            sum(IsNewSession),

        ActivityEvents =
            count(),

        ProductNames =
            make_set(
                Product,
                20
            ),

        FirstSeen =
            min(Timestamp),

        LastSeen =
            max(Timestamp),

        IsSanctioned =
            max(IsSanctioned)

      by
        PolicyKey,
        Provider;


// ============================================================
// JOIN EVIDENCE TYPES
// ============================================================

ProductSummary

| join kind=leftouter hint.strategy=broadcast (
    EvidenceSummary
) on PolicyKey


// ============================================================
// FRIENDLY DISPLAY
// ============================================================

| extend Governance =
    iff(
        IsSanctioned,
        "🟢 Sanctioned",
        "🔴 Unsanctioned"
    )

| extend ProductList =
    strcat_array(
        array_sort_asc(
            ProductNames
        ),
        ", "
    )

| extend AIProduct =
    strcat(
        Provider,
        " - ",
        ProductList
    )

| extend ActiveDaysDisplay =
    strcat(
        tostring(ActiveDays),
        " of ",
        tostring(RangeDays),
        iff(
            RangeDays == 1,
            " day",
            " days"
        )
    )

| extend Evidence =
    strcat_array(
        array_sort_asc(
            EvidenceTypes
        ),
        ", "
    )


// ============================================================
// ADOPTION PERCENT
//
// Useful for sorting/filtering while retaining the friendly
// "12 of 30 days" display.
// ============================================================

| extend ActiveDayPercent =
    round(
        100.0
        *
        todouble(ActiveDays)
        /
        todouble(RangeDays),
        1
    )


// ============================================================
// SORT
// ============================================================

| order by
    ActiveDayPercent desc,
    Users desc,
    ObservedSessions desc,
    ActivityEvents desc


// ============================================================
// OUTPUT
// ============================================================

| project
    Governance,

    ['AI Product'] =
        AIProduct,

    Provider,

    ['Active Days'] =
        ActiveDaysDisplay,

    ['Active Day %'] =
        ActiveDayPercent,

    Users,

    Devices,

    ['Observed Sessions'] =
        ObservedSessions,

    ['Activity Events'] =
        ActivityEvents,

    Evidence,

    ['First Seen'] =
        FirstSeen,

    ['Last Seen'] =
        LastSeen,

    PolicyKey

// ============================================================
// SUMMARY TILE COUNTS
// Counts catalogue coverage, not observed activity.
// ============================================================

// AI SERVICES CATALOGUE
let AIServiceCatalogue =
    externaldata(
        Provider:string,
        Product:string,
        Domain:string,
        Category:string,
        Sanctioned:bool,
        RiskType:string,
        SourceURL:string,
        ProcessName:string,
        ProcessProductName:string,
        ProcessPublisher:string
    )
    [
        @"https://raw.githubusercontent.com/Azure/Azure-Sentinel/master/Sample%20Data/AIGovernance/ai_domains.csv"
    ]
    with (
        format="csv",
        ignoreFirstRecord=true
    )
    | where isnotempty(Provider) and isnotempty(Product)
    | extend ProviderProductKey = strcat(
        tolower(trim(@"^\s+|\s+$", Provider)),
        "|",
        tolower(trim(@"^\s+|\s+$", Product))
    )
    | summarize by Provider, Product, ProviderProductKey;

// AI AGENTS CATALOGUE
let AIAgentCatalogue =
    externaldata(
        Name:string,
        Category:string,
        MatchField:string,
        Pattern:string,
        MatchType:string,
        RiskLevel:string,
        DefaultAction:string,
        Reason:string,
        SourceURL:string,
        Vendor:string,
        SourceFrom:string,
        TelemetrySource:string
    )
    [
        @"https://raw.githubusercontent.com/Azure/Azure-Sentinel/master/Sample%20Data/AIGovernance/ai_agent_watchlist.csv"
    ]
    with (
        format="csv",
        ignoreFirstRecord=true
    )
    | where isnotempty(Vendor) and isnotempty(Name)
    | extend VendorAgentKey = strcat(
        tolower(trim(@"^\s+|\s+$", Vendor)),
        "|",
        tolower(trim(@"^\s+|\s+$", Name))
    )
    | summarize by Vendor, Name, VendorAgentKey;

// DEEP SEARCH CATALOGUE
// Keep the current Quorum Cyber URL until the Microsoft file exists.
let DeepSearchCatalogue =
    externaldata(
        SearchKey:string,
        Provider:string,
        Product:string,
        ProductAliases:string,
        IndicatorType:string,
        IndicatorValue:string,
        MatchRule:string,
        MatchField:string,
        Category:string,
        RiskType:string,
        MatchConfidence:string,
        Active:string,
        Sanctioned:string,
        ReportableByDefault:string,
        SourceURL:string,
        SourceLists:string,
        TelemetrySource:string,
        Notes:string
    )
    [
        @"https://raw.githubusercontent.com/Azure/Azure-Sentinel/refs/heads/master/Sample%20Data/AIGovernance/ai_consolidated_sentinel_watchlist.csv"
    ]
    with (
        format="csv",
        ignoreFirstRecord=true
    )
    | where Active =~ "true"
    | where IndicatorType in (
        "domain",
        "process_name",
        "product_name",
        "publisher",
        "process_commandline"
    )
    | where isnotempty(Provider) and isnotempty(Product)
    | extend ProviderProductKey = strcat(
        tolower(trim(@"^\s+|\s+$", Provider)),
        "|",
        tolower(trim(@"^\s+|\s+$", Product))
    )
    | summarize by Provider, Product, ProviderProductKey;

// TILE VALUES
let AIServiceProviders =
    toscalar(AIServiceCatalogue | summarize dcount(Provider));

let AIServiceProducts =
    toscalar(AIServiceCatalogue | summarize dcount(ProviderProductKey));

let AIAgentProviders =
    toscalar(AIAgentCatalogue | summarize dcount(Vendor));

let AIAgentProducts =
    toscalar(AIAgentCatalogue | summarize dcount(VendorAgentKey));

let DeepSearchProviders =
    toscalar(DeepSearchCatalogue | summarize dcount(Provider));

let DeepSearchProducts =
    toscalar(DeepSearchCatalogue | summarize dcount(ProviderProductKey));

union
    (print SortOrder=1, Metric="🏢 AI Service Providers", Value=tolong(AIServiceProviders)),
    (print SortOrder=2, Metric="🤖 AI Service Products", Value=tolong(AIServiceProducts)),
    (print SortOrder=3, Metric="🧩 AI Agent Providers", Value=tolong(AIAgentProviders)),
    (print SortOrder=4, Metric="🛠️ AI Agents / Tools", Value=tolong(AIAgentProducts)),
    (print SortOrder=5, Metric="🔎 Deep Search Providers", Value=tolong(DeepSearchProviders)),
    (print SortOrder=6, Metric="📚 Deep Search Products", Value=tolong(DeepSearchProducts))
| order by SortOrder asc
| project Metric, Value
